# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA PAYLAŞMA VE YARDIMLAŞMA KAVRAMLARI</text>\n  <rect x="30" y="55" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İnfak (الإنفاق)</text>\n  <text x="130" y="110" text-anchor="middle" font-size="11.5" fill="#334155">Allah\'ın (c.c.) rızasını</text>\n  <text x="130" y="130" text-anchor="middle" font-size="11.5" fill="#334155">kazanmak amacıyla kişinin</text>\n  <text x="130" y="150" text-anchor="middle" font-size="11.5" fill="#334155">sahip olduğu mallardan</text>\n  <text x="130" y="170" text-anchor="middle" font-size="11.5" fill="#334155">harcama yapmasıdır.</text>\n  <text x="130" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Zekât ve sadakayı kapsar.</text>\n  <rect x="250" y="55" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Îsâr (الإيثار - Diğergamlık)</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11.5" fill="#334155">Kişinin kendisi ihtiyaç</text>\n  <text x="350" y="130" text-anchor="middle" font-size="11.5" fill="#334155">içinde bulunsa bile sahip</text>\n  <text x="350" y="150" text-anchor="middle" font-size="11.5" fill="#334155">olduğu imkânları mümin</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11.5" fill="#334155">kardeşine tercih etmesidir.</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Cömertliğin zirve noktasıdır.</text>\n  <rect x="470" y="55" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Birr (البر - Gerçek İyilik)</text>\n  <text x="570" y="110" text-anchor="middle" font-size="11.5" fill="#334155">"Sevdiğiniz şeylerden</text>\n  <text x="570" y="130" text-anchor="middle" font-size="11.5" fill="#334155">Allah yolunda harcamadıkça</text>\n  <text x="570" y="150" text-anchor="middle" font-size="11.5" fill="#334155">gerçek iyiliğe (birre)</text>\n  <text x="570" y="170" text-anchor="middle" font-size="11.5" fill="#334155">ulaşamazsınız."</text>\n  <text x="570" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">(Âl-i İmrân Suresi, 92. ayet)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PAYLAŞMANIN BİREYSEL VE TOPLUMSAL FAYDALARI</text>\n  <rect x="40" y="55" width="295" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Bireye Kazandırdıkları</text>\n  <text x="60" y="110" font-size="11.5" fill="#334155">• Kalpteki cimrilik, bencillik ve mal hırsını temizler.</text>\n  <text x="60" y="138" font-size="11.5" fill="#334155">• Allah\'ın (c.c.) sevgisini ve rızasını kazandırır.</text>\n  <text x="60" y="166" font-size="11.5" fill="#334155">• Sahip olunan nimetlere şükür bilinci geliştirir.</text>\n  <text x="60" y="194" font-size="11.5" fill="#334155">• Malın bereketlenmesini ve arınmasını sağlar.</text>\n  <text x="60" y="220" font-size="11.5" font-weight="bold" fill="#9d174d">• Manevi huzur ve mutluluk verir.</text>\n  <rect x="365" y="55" width="295" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Topluma Kazandırdıkları</text>\n  <text x="385" y="110" font-size="11.5" fill="#334155">• Zengin ile yoksul arasındaki uçurumu azaltır.</text>\n  <text x="385" y="138" font-size="11.5" fill="#334155">• Kıskançlık, kin ve haset duygularını önler.</text>\n  <text x="385" y="166" font-size="11.5" fill="#334155">• Sosyal adaleti ve ekonomik dengeyi korur.</text>\n  <text x="385" y="194" font-size="11.5" fill="#334155">• Sevgi, saygı, güven ve kardeşlik bağlarını güçlendirir.</text>\n  <text x="385" y="220" font-size="11.5" font-weight="bold" fill="#1e40af">• Toplumsal barış ve dayanışmayı tesis eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARİHTEKİ EN GÜZEL ÖRNEK: ENSAR - MUHACİR KARDEŞLİĞİ</text>\n  <rect x="40" y="60" width="230" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="155" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">MUHACİR (المهاجرون)</text>\n  <text x="155" y="118" text-anchor="middle" font-size="11.5" fill="#334155">İnançlarını yaşamak için</text>\n  <text x="155" y="138" text-anchor="middle" font-size="11.5" fill="#334155">Mekke\'deki evlerini ve</text>\n  <text x="155" y="158" text-anchor="middle" font-size="11.5" fill="#334155">mallarını bırakıp Medine\'ye</text>\n  <text x="155" y="178" text-anchor="middle" font-size="11.5" fill="#334155">hicret eden Müslümanlar.</text>\n  <rect x="285" y="95" width="130" height="100" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="128" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">MUÂHÂT</text>\n  <text x="350" y="150" text-anchor="middle" font-size="11" fill="#475569">Kardeşlik Antlaşması</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">(Haşr Suresi, 9. Ayet)</text>\n  <rect x="430" y="60" width="230" height="170" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="545" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">ENSAR (الأنصار)</text>\n  <text x="545" y="118" text-anchor="middle" font-size="11.5" fill="#334155">Mekke\'den gelen muhacirlere</text>\n  <text x="545" y="138" text-anchor="middle" font-size="11.5" fill="#334155">kucak açan, evlerini ve</text>\n  <text x="545" y="158" text-anchor="middle" font-size="11.5" fill="#334155">rızıklarını onlarla paylaşan</text>\n  <text x="545" y="178" text-anchor="middle" font-size="11.5" fill="#334155">Medineli Müslümanlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
